          "Ăn ngay khi thức ăn còn nóng; không để thức ăn thừa qua bữa; không dùng thức ăn ôi, có mùi lạ.",
          "Đựng thức ăn trong hộp có nắp; không để thức ăn trên giường, đầu tủ lâu."
