          "Chảy máu cam, chảy máu chân răng nhiều; nôn ra máu, đi cầu phân đen; kinh nguyệt kéo dài.",
          "Li bì, vật vã, bứt rứt; tay chân lạnh, vã mồ hôi.",
          "Tiểu ít hoặc không tiểu trong 6 giờ.",
          "Phụ nữ mang thai, trẻ nhũ nhi, người cao tuổi, người có bệnh mạn tính bị sốt xuất huyết nên được khám và theo dõi tại cơ sở y tế."
