          "Thu gom, hủy vỏ chai, lon, lốp xe, vật dụng có thể đọng nước.",
          "Ngủ màn, mặc áo dài tay, dùng kem xua muỗi; phát quang bụi rậm.",
          "Phối hợp với y tế địa phương khi có đợt phun hóa chất diệt muỗi."
