     "Cho trẻ ăn mềm, uống đủ nước; hạ sốt bằng paracetamol theo cân nặng.",
     "Giật mình, sốt cao khó hạ, nôn nhiều, li bì, thở nhanh: đến bệnh viện ngay.",
     "Rửa tay bằng xà phòng; lau sạch đồ chơi, sàn nhà; cho trẻ nghỉ học."
